def transform(grid):
    from collections import Counter, deque

    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]

    # Separate foreground into horizontal bands divided by empty rows.
    bands = []
    r = 0
    while r < h:
        while r < h and all(v == background for v in grid[r]):
            r += 1
        if r == h:
            break
        band = []
        while r < h and any(v != background for v in grid[r]):
            band.append(r)
            r += 1
        bands.append(band)

    candidates = []
    for band in bands:
        band_set = set(band)
        seen = set()
        components = []

        for y in band:
            for x in range(w):
                if grid[y][x] == background or (y, x) in seen:
                    continue
                q = deque([(y, x)])
                seen.add((y, x))
                comp = []
                while q:
                    cy, cx = q.popleft()
                    comp.append((cy, cx))
                    for ny, nx in ((cy - 1, cx), (cy + 1, cx),
                                   (cy, cx - 1), (cy, cx + 1)):
                        if (ny in band_set and 0 <= nx < w
                                and grid[ny][nx] != background
                                and (ny, nx) not in seen):
                            seen.add((ny, nx))
                            q.append((ny, nx))
                components.append(comp)

        if components:
            rightmost_comp = max(components, key=lambda c: max(x for y, x in c))
            rightmost = max(x for y, x in rightmost_comp)
            if rightmost < w - 1:
                candidates.append((rightmost, rightmost_comp))

    if candidates:
        _, comp = candidates[0]
        rightmost = max(x for y, x in comp)
        for y, x in comp:
            if x == rightmost:
                for nx in range(rightmost + 1, w):
                    out[y][nx] = 1

    return out
